INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('REPEL','Repel', null,'An item that prevents weak wild Pokemon from appearing for 100 steps after its use.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('SUPERREPEL','Super Repel', null,'An item that prevents weak wild Pokemon from appearing for 200 steps after its use.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('MAXREPEL','Max Repel', null,'An item that prevents weak wild Pokemon from appearing for 250 steps after its use.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('BLACKFLUTE','Black Flute', null,'A black flute made from blown glass. Its melody makes wild Pokemon less likely to appear.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('WHITEFLUTE','White Flute', null,'A white flute made from blown glass. Its melody makes wild Pokemon more likely to appear.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('HONEY','Honey', null,'A sweet honey with a lush aroma that attracts wild Pokemon when used in tall grass, in caves, or elsewhere.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('REDSHARD','Red Shard', null,'A small red shard. It appears to be from some sort of implement made long ago.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('YELLOWSHARD','Yellow Shard', null,'A small yellow shard. It appears to be from some sort of implement made long ago.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('BLUESHARD','Blue Shard', null,'A small blue shard. It appears to be from some sort of implement made long ago.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('GREENSHARD','Green Shard', null,'A small green shard. It appears to be from some sort of implement made long ago.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('FIRESTONE','Fire Stone', null,'A peculiar stone that makes certain species of Pokemon evolve. It is colored orange.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('THUNDERSTONE','Thunder Stone', null,'A peculiar stone that makes certain species of Pokemon evolve. It has a thunderbolt pattern.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('WATERSTONE','Water Stone', null,'A peculiar stone that makes certain species of Pokemon evolve. It is a clear, light blue.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('LEAFSTONE','Leaf Stone', null,'A peculiar stone that makes certain species of Pokemon evolve. It has a leaf pattern.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('MOONSTONE','Moon Stone', null,'A peculiar stone that makes certain species of Pokemon evolve. It is as black as the night sky.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('SUNSTONE','Sun Stone', null,'A peculiar stone that makes certain species of Pokemon evolve. It is as red as the sun.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('DUSKSTONE','Dusk Stone', null,'A peculiar stone that makes certain species of Pokemon evolve. It is as dark as dark can be.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('DAWNSTONE','Dawn Stone', null,'A peculiar stone that makes certain species of Pokemon evolve. It sparkles like eyes.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('SHINYSTONE','Shiny Stone', null,'A peculiar stone that makes certain species of Pokemon evolve. It shines with a dazzling light.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('ICESTONE','Ice Stone', null,'A peculiar stone that makes certain species of Pokemon evolve. It has a snowflake pattern.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('SWEETAPPLE','Sweet Apple', null,'A peculiar apple that can make a certain species of Pokemon evolve. It''s exceptionally sweet.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TARTAPPLE','Tart Apple', null,'A peculiar apple that can make a certain species of Pokemon evolve. It''s exceptionally tart.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('CRACKEDPOT','Cracked Pot', null,'A peculiar cracked teapot that can make a certain species of Pokemon evolve. It makes delicious tea.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('CHIPPEDPOT','Chipped Pot', null,'A peculiar chipped teapot that can make a certain species of Pokemon evolve. It makes delicious tea.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('GALARICACUFF','Galarica Cuff', null,'A cuff made from woven-together Galarica Twigs. Giving it to a Galarian Slowpoke would make it very happy.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('GALARICAWREATH','Galarica Wreath', null,'A wreath made from woven-together Galarica Twigs. A Galarian Slowpoke wearing this would be very happy.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('REDAPRICORN','Red Apricorn', null,'A red Apricorn. It assails your nostrils.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('YELLOWAPRICORN','Yellow Apricorn', null,'A yellow Apricorn. It has an invigorating scent.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('BLUEAPRICORN','Blue Apricorn', null,'A blue Apricorn. It smells a bit like grass.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('GREENAPRICORN','Green Apricorn', null,'A green Apricorn. It has a mysterious, aromatic scent.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('PINKAPRICORN','Pink Apricorn', null,'A pink Apricorn. It has a nice, sweet scent.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('WHITEAPRICORN','White Apricorn', null,'A white Apricorn. It doesn''t smell like anything.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('BLACKAPRICORN','Black Apricorn', null,'A black Apricorn. It has an indescribable scent.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('HELIXFOSSIL','Helix Fossil', null,'A fossil of an ancient Pokemon that lived in the sea. It appears to be part of a seashell.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('DOMEFOSSIL','Dome Fossil', null,'A fossil of an ancient Pokemon that lived in the sea. It appears to be part of a shell.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('OLDAMBER','Old Amber', null,'A piece of amber that contains the genes of an ancient Pokemon. It is clear with a reddish tint.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('ROOTFOSSIL','Root Fossil', null,'A fossil of an ancient Pokemon that lived in the sea. It appears to be part of a plant root.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('CLAWFOSSIL','Claw Fossil', null,'A fossil of an ancient Pokemon that lived in the sea. It appears to be part of a claw.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('SKULLFOSSIL','Skull Fossil', null,'A fossil from a prehistoric Pokemon that lived on the land. It appears to be part of a head.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('ARMORFOSSIL','Armor Fossil', null,'A fossil from a prehistoric Pokemon that lived on the land. It appears to be part of a collar.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('COVERFOSSIL','Cover Fossil', null,'A fossil of an ancient Pokemon that lived in the sea in ancient times. It appears to be part of its back.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('PLUMEFOSSIL','Plume Fossil', null,'A fossil of an ancient Pokemon that flew in the sky in ancient times. It appears to be part of its wing.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('JAWFOSSIL','Jaw Fossil', null,'A fossil from a prehistoric Pokemon that once lived on the land. It appears to be part of a large jaw.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('SAILFOSSIL','Sail Fossil', null,'A fossil from a prehistoric Pokemon that once lived on the land. It looks like the impression from a skin sail.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('FOSSILIZEDBIRD','Fossilized Bird', null,'The fossil of an ancient Pokemon that once soared through the sky. What it looked like is a mystery.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('FOSSILIZEDFISH','Fossilized Fish', null,'The fossil of an ancient Pokemon that once lived in the sea. What it looked like is a mystery.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('FOSSILIZEDDRAKE','Fossilized Drake', null,'The fossil of an ancient Pokemon that once roamed the land. What it looked like is a mystery.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('FOSSILIZEDDINO','Fossilized Dino', null,'The fossil of an ancient Pokemon that once lived in the sea. What it looked like is a mystery.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('PRETTYFEATHER','Pretty Feather', null,'Though this feather is beautiful, it''s just a regular feather and has no effect on Pokemon.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TINYMUSHROOM','Tiny Mushroom', null,'A small and rare mushroom. It is sought after by collectors.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('BIGMUSHROOM','Big Mushroom', null,'A large and rare mushroom. It is sought after by collectors.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('BALMMUSHROOM','Balm Mushroom', null,'A rare mushroom which gives off a nice fragrance. A maniac will buy it for a high price.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('PEARL','Pearl', null,'A somewhat-small pearl that sparkles in a pretty silver color. It can be sold cheaply to shops.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('BIGPEARL','Big Pearl', null,'A quite-large pearl that sparkles in a pretty silver color. It can be sold at a high price to shops.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('PEARLSTRING','Pearl String', null,'Very large pearls that sparkle in a pretty silver color. A maniac will buy them for a high price.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('STARDUST','Stardust', null,'Lovely, red-colored sand with a loose, silky feel. It can be sold at a high price to shops.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('STARPIECE','Star Piece', null,'A shard of a pretty gem that sparkles in a red color. It can be sold at a high price to shops.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('COMETSHARD','Comet Shard', null,'A shard which fell to the ground when a comet approached. A maniac will buy it for a high price.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('NUGGET','Nugget', null,'A nugget of pure gold that gives off a lustrous gleam. It can be sold at a high price to shops.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('BIGNUGGET','Big Nugget', null,'A big nugget of pure gold that gives off a lustrous gleam. A maniac will buy it for a high price.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('HEARTSCALE','Heart Scale', null,'A pretty, heart-shaped scale that is extremely rare. It glows faintly in the colors of the rainbow.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('SLOWPOKETAIL','Slowpoke Tail', null,'A very tasty tail of something. It can be sold at a high price to shops.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('RAREBONE','Rare Bone', null,'A bone that is extremely valuable for Pokemon archaeology. It can be sold for a high price to shops.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('RELICCOPPER','Relic Copper', null,'A copper coin used in a civilization about 3,000 years ago. A maniac will buy it for a high price.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('RELICSILVER','Relic Silver', null,'A silver coin used in a civilization about 3,000 years ago. A maniac will buy it for a high price.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('RELICGOLD','Relic Gold', null,'A gold coin used in a civilization about 3,000 years ago. A maniac will buy it for a high price.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('RELICVASE','Relic Vase', null,'A vase made in a civilization about 3,000 years ago. A maniac will buy it for a high price.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('RELICBAND','Relic Band', null,'A bracelet made in a civilization about 3,000 years ago. A maniac will buy it for a high price.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('RELICSTATUE','Relic Statue', null,'A stone figure made in a civilization about 3,000 years ago. A maniac will buy it for a high price.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('RELICCROWN','Relic Crown', null,'A crown made in a civilization about 3,000 years ago. A maniac will buy it for a high price.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('GROWTHMULCH','Growth Mulch', null,'A fertilizer to be spread on soft soil in regions where Berries are grown. A maniac will buy it for a high price.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('DAMPMULCH','Damp Mulch', null,'A fertilizer to be spread on soft soil in regions where Berries are grown. A maniac will buy it for a high price.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('STABLEMULCH','Stable Mulch', null,'A fertilizer to be spread on soft soil in regions where Berries are grown. A maniac will buy it for a high price.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('GOOEYMULCH','Gooey Mulch', null,'A fertilizer to be spread on soft soil in regions where Berries are grown. A maniac will buy it for a high price.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('SHOALSALT','Shoal Salt', null,'Pure salt that can be discovered deep inside the Shoal Cave. A maniac will buy it for a high price.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('SHOALSHELL','Shoal Shell', null,'A pretty seashell that can be found deep inside the Shoal Cave. A maniac will buy it for a high price.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('ODDKEYSTONE','Odd Keystone', null,'A vital item that is needed to keep a stone tower from collapsing. Voices can be heard from it occasionally.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('REDNECTAR','Red Nectar', null,'A flower nectar obtained at Ula''ula Meadow. It changes the form of certain species of Pokemon.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('YELLOWNECTAR','Yellow Nectar', null,'A flower nectar obtained at Melemele Meadow. It changes the form of certain species of Pokemon.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('PINKNECTAR','Pink Nectar', null,'A flower nectar obtained from shrubs on Royal Avenue. It changes the form of certain species of Pokemon.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('PURPLENECTAR','Purple Nectar', null,'A flower nectar obtained at Poni Meadow. It changes the form of certain species of Pokemon.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('AIRBALLOON','Air Balloon', null,'An item to be held by a Pokemon. The holder will float in the air until hit. Once hit, this item will burst.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('BRIGHTPOWDER','Bright Powder', null,'An item to be held by a Pokemon. It casts a tricky glare that lowers the opponent''s accuracy.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('EVIOLITE','Eviolite', null,'A mysterious evolutionary lump. When held, it raises the Defense and Sp. Def if the holder can still evolve.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('FLOATSTONE','Float Stone', null,'A very light stone. It reduces the weight of a Pokemon when held.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('DESTINYKNOT','Destiny Knot', null,'A long, thin, bright-red string to be held by a Pokemon. If the holder becomes infatuated, so does the foe.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('ROCKYHELMET','Rocky Helmet', null,'If the holder of this item takes damage, the attacker will also be damaged upon contact.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('ASSAULTVEST','Assault Vest', null,'An item to be held by a Pokemon. This offensive vest raises Sp. Def but prevents the use of status moves.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('SAFETYGOGGLES','Safety Goggles', null,'An item to be held by a Pokemon. They protect the holder from weather-related damage and powder.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('PROTECTIVEPADS','Protective Pads', null,'An item to be held by a Pokemon. They protect the holder from effects caused by making contact.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('HEAVYDUTYBOOTS','Heavy-Duty Boots', null,'These boots prevent the effects of traps set on the battlefield.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('UTILITYUMBRELLA','Utility Umbrella', null,'An item to be held by a Pokemon. This sturdy umbrella protects the holder from the effects of rain and sun.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('EJECTBUTTON','Eject Button', null,'If the holder is hit by an attack, it will switch with another Pokemon in your party.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('EJECTPACK','Eject Pack', null,'An item to be held by a Pokemon. When the holder''s stats are lowered, it will be switched out of battle.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('REDCARD','Red Card', null,'A card with a mysterious power. When the holder is struck by a foe, the attacker is removed from battle.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('SHEDSHELL','Shed Shell', null,'An item to be held by a Pokemon. This discarded carapace lets the holder switch out of battle without fail.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('SMOKEBALL','Smoke Ball', null,'An item to be held by a Pokemon. It enables the holder to flee from any wild Pokemon without fail.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('LUCKYEGG','Lucky Egg', null,'An item to be held by a Pokemon. It is an egg filled with happiness that earns extra Exp. Points in battle.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('EXPSHARE','Exp. Share', null,'An item to be held by a Pokemon. The holder gets a share of a battle''s Exp. Points without battling.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('AMULETCOIN','Amulet Coin', null,'An item to be held by a Pokemon. It doubles a battle''s prize money if the holding Pokemon joins in.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('SOOTHEBELL','Soothe Bell', null,'An item to be held by a Pokemon. The comforting chime of this bell calms the holder, making it friendly.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('CLEANSETAG','Cleanse Tag', null,'An item to be held by a Pokemon. It helps keep wild Pokemon away if the holder is the first one in the party.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('CHOICEBAND','Choice Band', null,'An item to be held by a Pokemon. This headband ups Attack, but allows the use of only one move.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('CHOICESPECS','Choice Specs', null,'An item to be held by a Pokemon. These curious glasses boost Sp. Atk but allows the use of only one move.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('CHOICESCARF','Choice Scarf', null,'An item to be held by a Pokemon. This scarf boosts Speed but allows the use of only one move.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('HEATROCK','Heat Rock', null,'A Pokemon held item that extends the duration of the move Sunny Day used by the holder.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('DAMPROCK','Damp Rock', null,'A Pokemon held item that extends the duration of the move Rain Dance used by the holder.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('SMOOTHROCK','Smooth Rock', null,'A Pokemon held item that extends the duration of the move Sandstorm used by the holder.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('ICYROCK','Icy Rock', null,'A Pokemon held item that extends the duration of the move Hail used by the holder.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TERRAINEXTENDER','Terrain Extender', null,'An item to be held by a Pokemon. It extends the duration of the terrain caused by the holder.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('LIGHTCLAY','Light Clay', null,'An item to be held by a Pokemon. Protective moves like Light Screen and Reflect will be effective longer.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('GRIPCLAW','Grip Claw', null,'A Pokemon held item that extends the duration of multiturn attacks like Bind and Wrap.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('BINDINGBAND','Binding Band', null,'A band that increases the power of binding moves when held.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('BIGROOT','Big Root', null,'A Pokemon held item that boosts the power of HP-stealing moves to let the holder recover more HP.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('BLACKSLUDGE','Black Sludge', null,'A held item that gradually restores the HP of Poison-type Pokemon. It inflicts damage on all other types.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('LEFTOVERS','Leftovers', null,'An item to be held by a Pokemon. The holder''s HP is gradually restored during battle.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('SHELLBELL','Shell Bell', null,'An item to be held by a Pokemon. The holder''s HP is restored a little every time it inflicts damage.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('MENTALHERB','Mental Herb', null,'An item to be held by a Pokemon. It snaps the holder out of infatuation. It can be used only once.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('WHITEHERB','White Herb', null,'An item to be held by a Pokemon. It restores any lowered stat in battle. It can be used only once.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('POWERHERB','Power Herb', null,'A single-use item to be held by a Pokemon. It allows the immediate use of a move that charges up first.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('ABSORBBULB','Absorb Bulb', null,'A consumable bulb. If the holder is hit by a Water-type move, its Sp. Atk will rise.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('CELLBATTERY','Cell Battery', null,'A consumable battery. If the holder is hit by an Electric-type move, its Attack will rise.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('LUMINOUSMOSS','Luminous Moss', null,'An item to be held by a Pokemon. It boosts Sp. Def if hit by a Water-type attack. It can only be used once.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('SNOWBALL','Snowball', null,'An item to be held by a Pokemon. It boosts Attack if hit by an Ice-type attack. It can only be used once.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('WEAKNESSPOLICY','Weakness Policy', null,'An item to be held by a Pokemon. The holder''s Attack and Sp. Atk sharply increase if hit by a move it''s weak to.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('BLUNDERPOLICY','Blunder Policy', null,'Raises Speed sharply when a Pokemon misses with a move because of accuracy.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('THROATSPRAY','Throat Spray', null,'Raises Sp. Atk when a Pokemon uses a sound-based move.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('ADRENALINEORB','Adrenaline Orb', null,'An item to be held by a Pokemon. It boosts Speed when intimidated. It can be used only once.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('ROOMSERVICE','Room Service', null,'An item to be held by a Pokemon. Lowers Speed when Trick Room takes effect.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('ELECTRICSEED','Electric Seed', null,'An item to be held by a Pokemon. It boosts Defense on Electric Terrain. It can only be used once.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('GRASSYSEED','Grassy Seed', null,'An item to be held by a Pokemon. It boosts Defense on Grassy Terrain. It can only be used once.');
