INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('POTION','Potion', null,'A spray-type medicine for treating wounds. It can be used to restore 20 HP to a single Pokemon.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('SUPERPOTION','Super Potion', null,'A spray-type medicine for treating wounds. It can be used to restore 60 HP to a single Pokemon.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('HYPERPOTION','Hyper Potion', null,'A spray-type medicine for treating wounds. It can be used to restore 120 HP to a single Pokemon.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('MAXPOTION','Max Potion', null,'A spray-type medicine for treating wounds. It can completely restore the max HP of a single Pokemon.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('FULLRESTORE','Full Restore', null,'A medicine that fully restores the HP and heals any status problems of a single Pokemon.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('SACREDASH','Sacred Ash', null,'It revives all fainted Pokemon. In doing so, it also fully restores their HP.');
