INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('BURNHEAL','Burn Heal', null,'A spray-type medicine. It heals a single Pokemon that is suffering from a burn.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('PARALYZEHEAL','Paralyze Heal', null,'A spray-type medicine. It eliminates paralysis from a single Pokemon.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('ICEHEAL','Ice Heal', null,'A spray-type medicine. It defrosts a Pokemon that has been frozen solid.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('FULLHEAL','Full Heal', null,'A spray-type medicine. It heals all the status problems of a single Pokemon.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('PEWTERCRUNCHIES','Pewter Crunchies', null,'Pewter City''s famous crunchy snack. They can be used to heal all status conditions of a single Pokemon.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('RAGECANDYBAR','Rage Candy Bar', null,'Mahogany Town''s famous candy. It can be used once to heal all the status conditions of a Pokemon.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('LAVACOOKIE','Lava Cookie', null,'Lavaridge Town''s local specialty. It heals all the status problems of one Pokemon.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('OLDGATEAU','Old Gateau', null,'Old Chateau''s hidden specialty. It heals all the status problems of a single Pokemon.');
