INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('MOOMOOMILK','Moomoo Milk', null,'Milk with a very high nutrition content. It restores the HP of one Pokemon by 100 points.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('ENERGYPOWDER','Energy Powder', null,'A very bitter medicinal powder. It can be used to restore 60 HP to a single Pokemon.');
