INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('MAXHONEY','Max Honey', null,'Honey that Dynamax Vespiquen produces. It has the same effect as a Max Revive.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('ETHER','Ether', null,'It restores the PP of a Pokemon''s selected move by a maximum of 10 points.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('MAXETHER','Max Ether', null,'It fully restores the PP of a single selected move that has been learned by the target Pokemon.');
