INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('SASSYMINT','Sassy Mint', null,'When a Pokemon smells this mint, its Sp. Def will grow more easily, but its Speed will grow more slowly.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TIMIDMINT','Timid Mint', null,'When a Pokemon smells this mint, its Speed will grow more easily, but its Attack will grow more slowly.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('HASTYMINT','Hasty Mint', null,'When a Pokemon smells this mint, its Speed will grow more easily, but its Defense will grow more slowly.');
