INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('ABILITYCAPSULE','Ability Capsule', null,'A capsule that allows a Pokemon with two Abilities to switch between these Abilities when it is used.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('ABILITYPATCH','Ability Patch', null,'A patch that allows a Pokemon with a regular Ability to have a rare Ability.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('EXPCANDYXS','Exp. Candy XS', null,'A candy packed with energy. When consumed, it will grant a Pokemon a very small amount of Exp. Points.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('EXPCANDYS','Exp. Candy S', null,'A candy packed with energy. When consumed, it will grant a Pokemon a small amount of Exp. Points.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('EXPCANDYM','Exp. Candy M', null,'A candy packed with energy. When consumed, it will grant a Pokemon a moderate amount of Exp. Points.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('EXPCANDYL','Exp. Candy L', null,'A candy packed with energy. When consumed, it will grant a Pokemon a large amount of Exp. Points.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('EXPCANDYXL','Exp. Candy XL', null,'A candy packed with energy. When consumed, it will grant a Pokemon a very large amount of Exp. Points.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('RARECANDY','Rare Candy', null,'A candy that is packed with energy. It raises the level of a single Pokemon by one.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('MASTERBALL','Master Ball', null,'The best Ball with the ultimate level of performance. It will catch any wild Pokemon without fail.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('ULTRABALL','Ultra Ball', null,'An ultra-performance Ball that provides a higher Pokemon catch rate than a Great Ball.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('GREATBALL','Great Ball', null,'A good, high-performance Ball that provides a higher Pokemon catch rate than a standard Poke Ball.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('POKEBALL','Poke Ball', null,'A device for catching wild Pokemon. It is thrown like a ball at the target. It is designed as a capsule system.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('SAFARIBALL','Safari Ball', null,'A special Poke Ball that is used only in the Safari Zone. It is decorated in a camouflage pattern.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('SPORTBALL','Sport Ball', null,'A special Poke Ball for the Bug-Catching Contest.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('NETBALL','Net Ball', null,'A somewhat different Poke Ball that works especially well on Water- and Bug-type Pokemon.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('DIVEBALL','Dive Ball', null,'A somewhat different Poke Ball that works especially well on Pokemon that live underwater.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('NESTBALL','Nest Ball', null,'A somewhat different Poke Ball that works especially well on weaker Pokemon in the wild.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('REPEATBALL','Repeat Ball', null,'A somewhat different Poke Ball that works especially well on Pokemon species that were previously caught.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TIMERBALL','Timer Ball', null,'A somewhat different Ball that becomes progressively better the more turns there are in a battle.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('LUXURYBALL','Luxury Ball', null,'A comfortable Poke Ball that makes a caught wild Pokemon quickly grow friendly.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('PREMIERBALL','Premier Ball', null,'A somewhat rare Poke Ball that has been specially made to commemorate an event of some sort.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('DUSKBALL','Dusk Ball', null,'A somewhat different Poke Ball that makes it easier to catch wild Pokemon at night or in dark places like caves.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('HEALBALL','Heal Ball', null,'A remedial Poke Ball that restores the caught Pokemon''s HP and eliminates any status problem.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('QUICKBALL','Quick Ball', null,'A somewhat different Poke Ball that provides a better catch rate if used at the start of a wild encounter.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('CHERISHBALL','Cherish Ball', null,'A quite rare Poke Ball that has been specially crafted to commemorate an occasion of some sort.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('FASTBALL','Fast Ball', null,'A Poke Ball that makes it easier to catch fast Pokemon.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('LEVELBALL','Level Ball', null,'A Poke Ball for catching Pokemon that are a lower level than your own.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('LUREBALL','Lure Ball', null,'A Poke Ball for catching Pokemon hooked by a Rod when fishing.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('HEAVYBALL','Heavy Ball', null,'A Poke Ball for catching very heavy Pokemon.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('LOVEBALL','Love Ball', null,'A Poke Ball for catching Pokemon that are the opposite gender of your Pokemon.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('FRIENDBALL','Friend Ball', null,'A Poke Ball that makes caught Pokemon more friendly.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('MOONBALL','Moon Ball', null,'A Poke Ball for catching Pokemon that evolve using the Moon Stone.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('DREAMBALL','Dream Ball', null,'A somewhat different Poke Ball that makes it easier to catch wild Pokemon while they''re asleep.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('BEASTBALL','Beast Ball', null,'A special Poke Ball designed to catch Ultra Beasts. It has a low success rate for catching others.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM01','TM01','FOCUSPUNCH','The user focuses its mind before launching a punch. This move fails if the user is hit before it is used.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM02','TM02','DRAGONCLAW','The user slashes the target with huge sharp claws.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM03','TM03','WATERPULSE','The user attacks the target with a pulsing blast of water. This may also confuse the target.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM04','TM04','CALMMIND','The user quietly focuses its mind and calms its spirit to raise its Sp. Atk and Sp. Def stats.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM05','TM05','ROAR','The target is scared off, and a different Pokemon is dragged out. In the wild, this ends the battle.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM06','TM06','TOXIC','A move that leaves the target badly poisoned. Its poison damage worsens every turn.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM07','TM07','HAIL','The user summons a hailstorm lasting five turns. It damages all Pokemon except Ice types.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM08','TM08','BULKUP','The user tenses its muscles to bulk up its body, raising both its Attack and Defense stats.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM09','TM09','BULLETSEED','The user forcefully shoots seeds at the target two to five times in a row.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM10','TM10','WORKUP','The user is roused, and its Attack and Sp. Atk stats increase.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM11','TM11','SUNNYDAY','The user intensifies the sun for five turns, powering up Fire-type moves and weakening Water-type moves.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM12','TM12','TAUNT','The target is taunted into a rage that allows it to use only attack moves for three turns.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM13','TM13','ICEBEAM','The target is struck with an icy-cold beam of energy. This may also leave the target frozen.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM14','TM14','BLIZZARD','A howling blizzard is summoned to strike opposing Pokemon. This may also leave them frozen.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM15','TM15','HYPERBEAM','The target is attacked with a powerful beam. The user can''t move on the next turn.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM16','TM16','LIGHTSCREEN','A wondrous wall of light is put up to reduce damage from special attacks for five turns.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM17','TM17','PROTECT','The user protects itself from all attacks. Its chance of failing rises if it is used in succession.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM18','TM18','RAINDANCE','The user summons a heavy rain for five turns, powering up Water-type moves and weakening Fire-type ones.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM19','TM19','GIGADRAIN','A nutrient-draining attack. The user''s HP is restored by half the damage taken by the target.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM20','TM20','SAFEGUARD','The user creates a protective field that prevents status conditions for five turns.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM21','TM21','DAZZLINGGLEAM','The user damages opposing Pokemon by emitting a powerful flash.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM22','TM22','SOLARBEAM','In this two-turn attack, the user gathers light, then blasts a bundled beam on the next turn.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM23','TM23','IRONTAIL','The target is slammed with a steel-hard tail. This may also lower the target''s Defense stat.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM24','TM24','THUNDERBOLT','A strong electric blast crashes down on the target. This may also leave the target with paralysis.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM25','TM25','THUNDER','A wicked thunderbolt is dropped on the target to inflict damage. This may also leave them with paralysis.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM26','TM26','EARTHQUAKE','The user sets off an earthquake that strikes every Pokemon around it.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM27','TM27','LOWSWEEP','The user makes a swift attack on the target''s legs, which lowers the target''s Speed stat.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM28','TM28','DIG','The user burrows into the ground, then attacks on the next turn. It can also be used to exit dungeons.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM29','TM29','PSYCHIC','The target is hit by a strong telekinetic force. This may also lower the target''s Sp. Def stat.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM30','TM30','SHADOWBALL','The user hurls a shadowy blob at the target. This may also lower the target''s Sp. Def stat.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM31','TM31','BRICKBREAK','The user attacks with a swift chop. It can also break barriers, such as Light Screen and Reflect.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM32','TM32','DOUBLETEAM','By moving rapidly, the user makes illusory copies of itself to raise its evasiveness.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM33','TM33','REFLECT','A wondrous wall of light is put up to reduce damage from physical attacks for five turns.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM34','TM34','SHOCKWAVE','The user strikes the target with a quick jolt of electricity. This attack never misses.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM35','TM35','FLAMETHROWER','The target is scorched with an intense blast of fire. This may also leave the target with a burn.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM36','TM36','SLUDGEBOMB','Unsanitary sludge is hurled at the target. This may also poison the target.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM37','TM37','SANDSTORM','A five-turn sandstorm is summoned to hurt all combatants except Rock, Ground, and Steel types.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM38','TM38','FIREBLAST','The target is attacked with an intense blast of all-consuming fire. This may also leave them with a burn.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM39','TM39','ROCKTOMB','Boulders are hurled at the target. This also lowers the target''s Speed stat by preventing its movement.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM40','TM40','AERIALACE','The user confounds the target with speed, then slashes. This attack never misses.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM41','TM41','TORMENT','The user torments and enrages the target, making it incapable of using the same move twice in a row.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM42','TM42','FACADE','This attack move doubles its power if the user is poisoned, burned, or paralyzed.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM43','TM43','VOLTSWITCH','After making its attack, the user rushes back to switch places with a party Pokemon in waiting.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM44','TM44','REST','The user goes to sleep for two turns. This fully restores the user''s HP and heals any status conditions.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM45','TM45','ATTRACT','If it is the opposite gender of the user, the target becomes infatuated and less likely to attack.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM46','TM46','THIEF','The user attacks and steals the target''s held item simultaneously.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM47','TM47','STEELWING','The target is hit with wings of steel. This may also raise the user''s Defense stat.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM48','TM48','SKILLSWAP','The user employs its psychic power to exchange Abilities with the target.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM49','TM49','SCALD','The user shoots boiling hot water at its target. This may also leave the target with a burn.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM50','TM50','OVERHEAT','The user attacks the target at full power. The attack''s recoil harshly lowers the user''s Sp. Atk stat.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM51','TM51','ROOST','The user lands and rests its body. This move restores the user''s HP by up to half of its max HP.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM52','TM52','FOCUSBLAST','The user heightens its mental focus and unleashes its power. This may also lower the target''s Sp. Def stat.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM53','TM53','ENERGYBALL','The user draws power from nature and fires it at the target. This may also lower the target''s Sp. Def stat.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM54','TM54','FALSESWIPE','A restrained attack that prevents the target from fainting. The target is left with at least 1 HP.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM55','TM55','BRINE','If the target''s HP is half or less, this attack will hit with double the power.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM56','TM56','FLING','The user flings its held item at the target to attack. This move''s power and effects depend on the item.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM57','TM57','CHARGEBEAM','The user attacks the target with an electric charge. The user may use any remaining charge to raise its Sp. Atk.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM58','TM58','ENDURE','The user endures any attack with at least 1 HP. Its chance of failing rises if it is used in succession.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM59','TM59','DRAGONPULSE','The target is attacked with a shock wave generated by the user''s gaping mouth.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM60','TM60','DRAINPUNCH','An energy-draining punch. The user''s HP is restored by half the damage taken by the target.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM61','TM61','WILLOWISP','The user shoots a sinister flame at the target to inflict a burn.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM62','TM62','BUGBUZZ','The user generates a damaging sound wave by vibration. This may also lower the target''s Sp. Def stat.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM63','TM63','NASTYPLOT','The user stimulates its brain by thinking bad thoughts. This sharply raises the user''s Sp. Atk stat.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM64','TM64','EXPLOSION','The user attacks everything around it by causing a tremendous explosion. The user faints upon using this move.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM65','TM65','SHADOWCLAW','The user slashes with a sharp claw made from shadows. Critical hits land more easily.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM66','TM66','PAYBACK','The user stores power, then attacks. If the user moves after the target, this attack''s power will be doubled.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM67','TM67','RECYCLE','The user recycles a held item that has been used in battle so it can be used again.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM68','TM68','GIGAIMPACT','The user charges at the target using every bit of its power. The user can''t move on the next turn.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM69','TM69','ROCKPOLISH','The user polishes its body to reduce drag. This sharply raises the Speed stat.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM70','TM70','FLASH','The user flashes a light that lowers the target''s accuracy. It can also be used to illuminate caves.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM71','TM71','STONEEDGE','The user stabs the target from below with sharpened stones. Critical hits land more easily.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM72','TM72','AVALANCHE','The power of this attack move is doubled if the user has been hurt by the target in the same turn.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM73','TM73','THUNDERWAVE','The user launches a weak jolt of electricity that paralyzes the target.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM74','TM74','GYROBALL','The user tackles with a high-speed spin. This move is stronger the slower the user is than the target.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM75','TM75','SWORDSDANCE','A frenetic dance to uplift the fighting spirit. This sharply raises the user''s Attack stat.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM76','TM76','STEALTHROCK','The user lays a trap of levitating stones around the opposing team that hurt Pokemon that switch in.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM77','TM77','PSYCHUP','The user hypnotizes itself into copying any stat change made by the target.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM78','TM78','SNARL','The user yells as if it''s ranting about something, which lowers the Sp. Atk stats of opposing Pokemon.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM79','TM79','DARKPULSE','The user releases a horrible aura imbued with dark thoughts. This may also make the target flinch.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM80','TM80','ROCKSLIDE','Large boulders are hurled at opposing Pokemon to inflict damage. This may also make them flinch.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM81','TM81','XSCISSOR','The user slashes at the target by crossing its scythes or claws as if they were a pair of scissors.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM82','TM82','SLEEPTALK','While it is asleep, the user randomly uses one of the moves it knows.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM83','TM83','BULLDOZE','The user strikes everything around it by stomping down on the ground. This lowers the Speed of those hit.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM84','TM84','POISONJAB','The target is stabbed with a tentacle, arm, or the like steeped in poison. This may also poison them.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM85','TM85','DREAMEATER','The user eats the dreams of a sleeping target. The user''s HP is restored by half the damage dealt.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM86','TM86','GRASSKNOT','The user snares the target with grass and trips it. The heavier the target, the strong the move is.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM87','TM87','SWAGGER','The user enrages and confuses the target. However, this also sharply raises the target''s Attack stat.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM88','TM88','PLUCK','The user pecks the target. If the target is holding a Berry, the user eats it and gains its effect.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM89','TM89','UTURN','After making its attack, the user rushes back to switch places with a party Pokemon in waiting.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM90','TM90','SUBSTITUTE','The user creates a substitute for itself using some of its HP. The substitute serves as a decoy.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM91','TM91','FLASHCANNON','The user gathers all its light energy and releases it all at once. This may also lower the target''s Sp. Def stat.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM92','TM92','TRICKROOM','The user creates a bizarre area in which slower Pokemon get to move first for five turns.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM93','TM93','CUT','The target is cut with a scythe or claw.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM94','TM94','FLY','The user flies up into the sky and then strikes its target on the next turn.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM95','TM95','SURF','The user attacks everything around it by swamping its surroundings with a giant wave.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM96','TM96','STRENGTH','The target is slugged with a punch thrown at maximum power.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM97','TM97','DEFOG','A strong wind blows away the target''s barriers, such as Reflect, and lowers their evasiveness.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM98','TM98','ROCKSMASH','The user attacks with a punch that may lower the target''s Defense stat.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM99','TM99','WATERFALL','The user charges at the target and may make it flinch.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TM100','TM100','ROCKCLIMB','A charging attack that may also leave the foe confused.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('HM01','HM01','CUT','The target is cut with a scythe or claw. This can also be used to cut down thin trees.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('HM02','HM02','FLY','The user soars and then strikes on the next turn. This can also be used to fly to any familiar town.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('HM03','HM03','SURF','Attacks everything by swamping the surroundings with a giant wave. This can also be used to cross water.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('HM04','HM04','STRENGTH','The target is slugged with a punch thrown at maximum power. This can also be used to move heavy boulders.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('HM05','HM05','WATERFALL','The user charges at the target and may make it flinch. It can also be used to climb a waterfall.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('HM06','HM06','DIVE','Diving on the first turn, the user floats up and attacks on the second. It can be used to dive underwater.');
