INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('BICYCLE','Bicycle', null,'A folding Bicycle that enables much faster movement than the Running Shoes.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('OLDROD','Old Rod', null,'An old and beat-up fishing rod. Use it by any body of water to fish for wild aquatic Pokemon.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('GOODROD','Good Rod', null,'A new, good-quality fishing rod. Use it by any body of water to fish for wild aquatic Pokemon.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('SUPERROD','Super Rod', null,'An awesome, high-tech fishing rod. Use it by any body of water to fish for wild aquatic Pokemon.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('ITEMFINDER','Itemfinder', null,'A device used for finding items. If there is a hidden item nearby when it is used, it emits a signal.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('DOWSINGMACHINE','Dowsing Machine', null,'It checks for unseen items in the area and makes noise and lights when it finds something.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('POKERADAR','Poke Radar', null,'A tool that can search out Pokemon that are hiding in grass. Its battery is recharged as you walk.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('TOWNMAP','Town Map', null,'A very convenient map that can be viewed anytime. It even shows your present location.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('ESCAPEROPE','Escape Rope', null,'A long, durable rope. Use it to escape instantly from a cave or a dungeon.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('COINCASE','Coin Case', null,'A case for holding coins obtained at the Game Corner. It holds up to 99,999 coins.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('POKEFLUTE','Poke Flute', null,'A flute that is said to instantly awaken any Pokemon. It has a lovely tone.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('SOOTSACK','Soot Sack', null,'A sack used to gather and hold volcanic ash.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('SILPHSCOPE','Silph Scope', null,'A scope that makes unseeable Pokemon visible. It is made by Silph Co.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('DEVONSCOPE','Devon Scope', null,'A device by Devon that signals any unseeable Pokemon.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('SQUIRTBOTTLE','Squirt Bottle', null,'A watering can shaped like a Squirtle. It helps promote healthy growth of Berries planted in soft soil.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('SPRAYDUCK','Sprayduck', null,'A watering can shaped like a Psyduck. It helps promote healthy growth of Berries planted in soft soil.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('WAILMERPAIL','Wailmer Pail', null,'A nifty watering pail. Use it to promote strong growth in Berries planted in soft soil.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('SPRINKLOTAD','Sprinklotad', null,'A watering can shaped like a Lotad. It helps promote the healthy growth of any Berries planted in soft soil.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('GRACIDEA','Gracidea', null,'A flower sometimes bundled in bouquets to convey gratitude on special occasions like birthdays.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('REVEALGLASS','Reveal Glass', null,'A glass that reveals the truth. It is a mysterious glass that returns a Pokemon back to its original shape.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('PRISONBOTTLE','Prison Bottle', null,'A bottle believed to have been used to seal away the power of a certain Pokemon long, long ago.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('ROTOMCATALOG','Rotom Catalog', null,'A catalog of devices that Rotom like. Use the catalog to have Rotom hop in and out of the devices listed within.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('ZYGARDECUBE','Zygarde Cube', null,'An item in which Zygarde Cores and Cells are gathered. You can also use it to change Zygarde''s forms.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('DNASPLICERS','DNA Splicers', null,'A splicer that fuses Kyurem and a certain Pokemon. They are said to have been one in the beginning.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('DNASPLICERSUSED','DNA Splicers', null,'A splicer that separates Kyurem and a certain Pokemon when they have been fused.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('NSOLARIZER','N-Solarizer', null,'A machine to fuse Necrozma, which needs light, and Solgaleo.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('NSOLARIZERUSED','N-Solarizer', null,'A machine to separate Necrozma, which needed light, from Solgaleo.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('NLUNARIZER','N-Lunarizer', null,'A machine to fuse Necrozma, which needs light, and Lunala.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('NLUNARIZERUSED','N-Lunarizer', null,'A machine to separate Necrozma, which needed light, from Lunala.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('REINSOFUNITY','Reins of Unity', null,'Reins that people presented to the king. They unite Calyrex with its beloved steed.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('REINSOFUNITYUSED','Reins of Unity', null,'Reins that people presented to the king. They separate Calyrex and its beloved steed.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('OVALCHARM','Oval Charm', null,'An oval charm said to increase the chance of Eggs being found at the Day Care.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('SHINYCHARM','Shiny Charm', null,'A shiny charm said to increase the chance of finding a Shiny Pokemon.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('CATCHINGCHARM','Catching Charm', null,'A charm said to increase the chance of getting a critical catch. The charm doesn''t shake much.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('EXPCHARM','Exp. Charm', null,'A charm that increases the Exp. Points that Pokemon can get. A machine-like object is inside it.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('MEGARING','Mega Ring', null,'This ring contains an untold power that somehow enables Pokemon carrying Mega Stones to Mega Evolve.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('POKEMONBOXLINK','Pokemon Box Link', null,'A device that allows you to access the Pokemon storage system. There are some places where it won''t work.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('AURORATICKET','Aurora Ticket', null,'A ticket required to board the ship to Doxy Island. It glows beautifully.');
INSERT INTO Item (i_name, i_i_name, i_teaches, i_description) VALUES ('OLDSEAMAP','Old Sea Map', null,'A faded sea chart that shows the way to a certain island.');
